#!/usr/bin/env node
/**
 * Doctine · copies the Model Lab registry (ai-lab/registry/models.json) and the latest benchmark results
 * (ai-lab/reports/*-test.json) into netlify/lib/model-registry.generated.mjs, so the server (and the admin console's
 * AI page) can show them on Cloudflare, where there is no file system. Names, statuses and aggregate numbers only:
 * no data, no keys. tests/ai-registry.test.mjs fails if the generated file is out of date.
 *   node tools/model-registry-sync.mjs           (writes)        node tools/model-registry-sync.mjs --check
 */
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
const root = new URL("../", import.meta.url);
const reg = JSON.parse(readFileSync(new URL("ai-lab/registry/models.json", root), "utf8"));
const models = reg.models.map((m) => ({ id: m.id, kind: m.kind, ownership: m.ownership, status: m.status, tasks: m.tasks, evaluation: m.evaluation }));
const evaluations = readdirSync(new URL("ai-lab/reports/", root)).filter((f) => /-test\.json$/.test(f)).sort().map((f) => {
  const r = JSON.parse(readFileSync(new URL("ai-lab/reports/" + f, root), "utf8")), o = r.overall;
  return { model: r.model, input: r.input, split: r.split, dataset: r.dataset, date: r.date, documents: o.documents, row_precision: o.row_precision, row_recall: o.row_recall,
    value_acc: o.value_acc, wrong_values: Math.round(o.row_recall * o.gold_rows * (1 - o.value_acc)), misread: o.decimal_comma.misread, hallucinated_rows: o.hallucinated_rows, perfect_doc_rate: o.perfect_doc_rate };
});
const out = `// Generated by tools/model-registry-sync.mjs from ai-lab/registry/models.json and ai-lab/reports/. Do not edit.\nexport const MODEL_REGISTRY = ${JSON.stringify({ models, evaluations }, null, 1)};\n`;
const target = new URL("netlify/lib/model-registry.generated.mjs", root);
if (process.argv.includes("--check")) {
  let cur = ""; try { cur = readFileSync(target, "utf8"); } catch {}
  if (cur !== out) { console.error("netlify/lib/model-registry.generated.mjs is out of date: run node tools/model-registry-sync.mjs"); process.exit(1); }
  console.log("model registry: generated copy is up to date");
} else { writeFileSync(target, out); console.log(`model registry: ${models.length} models, ${evaluations.length} evaluations`); }
